181	fn capture_interactive(
182	    store: &FeedbackStore,
183	    tags: Vec<String>,
184	    no_deliver: bool,
185	    ui: &mut dyn UserInterface,
186	) -> Result<i32> {
187	    if !ui.is_interactive() {
188	        ui.error("Interactive mode not available. Provide feedback as argument.");
189	        return Ok(1);
190	    }
191	
192	    // Ask for category first
193	    let category_prompt = Prompt {
194	        key: "feedback_category".to_string(),
195	        question: "What kind of feedback?".to_string(),
196	        prompt_type: PromptType::Select {
197	            options: vec![
198	                PromptOption {
199	                    label: "Bug - something broke".to_string(),
200	                    value: "bug".to_string(),
201	                },
202	                PromptOption {
203	                    label: "UX - confusing or awkward".to_string(),
204	                    value: "ux".to_string(),
205	                },
206	                PromptOption {
207	                    label: "Feature - missing or incomplete".to_string(),
208	                    value: "feature".to_string(),
209	                },
210	                PromptOption {
211	                    label: "Other".to_string(),
212	                    value: "other".to_string(),
213	                },
214	            ],
215	        },
216	        default: None,
217	    };
218	
219	    let category = match ui.prompt(&category_prompt)? {
220	        PromptResult::String(s) => s,
221	        _ => "other".to_string(),
222	    };
223	
224	    let prompt = Prompt {
225	        key: "feedback_message".to_string(),
226	        question: "Describe your feedback:".to_string(),
227	        prompt_type: PromptType::Input,
228	        default: None,
229	    };
230	
231	    let result = ui.prompt(&prompt)?;
232	    let message = match result {
233	        PromptResult::String(s) => s,
234	        _ => String::new(),
235	    };
236	
237	    if message.is_empty() {
238	        ui.warning("No feedback provided");
239	        return Ok(1);
240	    }
241	
242	    // Merge category into tags
243	    let mut all_tags = tags;
244	    if !category.is_empty() && category != "other" {
245	        all_tags.insert(0, category.clone());
246	    }
247	
248	    let all_tags = if all_tags.is_empty() {
249	        let tag_prompt = Prompt {
250	            key: "feedback_tags".to_string(),
251	            question: "Tags (optional, comma-separated):".to_string(),
252	            prompt_type: PromptType::Input,
253	            default: None,
254	        };
255	
256	        match ui.prompt(&tag_prompt)? {
257	            PromptResult::String(s) if !s.is_empty() => {
258	                s.split(',').map(|s| s.trim().to_string()).collect()
259	            }
260	            _ => vec![],
261	        }
262	    } else {
263	        all_tags
264	    };
265	
266	    capture_feedback(store, &message, &category, all_tags, None, no_deliver, ui)
267	}
