9	/// Check for updates and prompt user if update available.
10	///
11	/// Returns true if an update was executed.
12	///
13	/// Requires full `UserInterface` — uses `OutputWriter` (messages),
14	/// `Prompter` (confirm prompt), and `UiState` (interactivity check).
15	pub fn check_and_prompt_update(ui: &mut dyn UserInterface) -> Result<bool> {
16	    // Only check in interactive mode
17	    if !ui.is_interactive() {
18	        return Ok(false);
19	    }
20	
21	    // Check for updates
22	    let info = match check_for_updates() {
23	        Some(info) => info,
24	        None => return Ok(false),
25	    };
26	
27	    // No update available
28	    if !info.update_available {
29	        return Ok(false);
30	    }
31	
32	    // Detect install method
33	    let method = detect_install_method();
34	
35	    // Prompt for update
36	    if prompt_for_update(ui, &info, &method)? {
37	        execute_update(&method)?;
38	        return Ok(true);
39	    }
40	
41	    Ok(false)
42	}
43	
44	/// Prompt the user to update.
45	fn prompt_for_update(
46	    ui: &mut dyn UserInterface,
47	    info: &UpdateInfo,
48	    method: &InstallMethod,
49	) -> Result<bool> {
50	    ui.message(&format!(
51	        "A new version of bivvy is available: {} -> {}",
52	        info.current, info.latest
53	    ));
54	
55	    if !method.supports_auto_update() {
56	        if let Some(url) = &info.release_url {
57	            ui.message(&format!("Download from: {}", url));
58	        }
59	        return Ok(false);
60	    }
61	
62	    let prompt = Prompt {
63	        key: "update_bivvy".to_string(),
64	        question: "Would you like to update now?".to_string(),
65	        prompt_type: PromptType::Confirm,
66	        default: Some("true".to_string()),
67	    };
68	
69	    match ui.prompt(&prompt)? {
70	        PromptResult::Bool(confirmed) => Ok(confirmed),
71	        _ => Ok(false),
72	    }
73	}
74	
75	/// Execute the update using the appropriate method.
76	fn execute_update(method: &InstallMethod) -> Result<()> {
77	    let command = method
78	        .update_command()
79	        .ok_or_else(|| anyhow::anyhow!("No update command for install method"))?;
80	
81	    let parts: Vec<&str> = command.split_whitespace().collect();
82	    if parts.is_empty() {
83	        anyhow::bail!("Empty update command");
84	    }
85	
86	    let status = Command::new(parts[0]).args(&parts[1..]).status()?;
87	
88	    if !status.success() {
89	        anyhow::bail!("Update command failed with exit code: {:?}", status.code());
90	    }
91	
92	    Ok(())
93	}
94	
95	/// Show update notification without prompting.
96	///
97	/// Only requires `OutputWriter` — displays a message but does not prompt.
98	pub fn show_update_notification(ui: &mut dyn OutputWriter) {
99	    if let Some(info) = check_for_updates() {
100	        if info.update_available {
101	            ui.message(&format!(
102	                "Update available: {} -> {} (run `bivvy update` to upgrade)",
103	                info.current, info.latest
104	            ));
105	        }
106	    }
107	}
108	
109	/// Thread-safe flag for suppressing update notifications within the current process.
110	static SUPPRESS_UPDATE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
111	
112	/// Suppress update notification for the current session.
113	///
114	/// Uses a process-local atomic flag instead of mutating the environment.
115	pub fn suppress_notification() {
116	    SUPPRESS_UPDATE.store(true, std::sync::atomic::Ordering::Relaxed);
117	}
118	
119	/// Check if update notification is suppressed.
120	pub fn is_notification_suppressed() -> bool {
121	    SUPPRESS_UPDATE.load(std::sync::atomic::Ordering::Relaxed)
122	}
