11	/// UI implementation for non-interactive mode.
12	///
13	/// Used by every command (init, status, list, run, …) when running
14	/// without a TTY. Run-path workflow chrome lives in
15	/// [`crate::runner::display::NonInteractiveWorkflowDisplay`] — this
16	/// type only handles generic [`UserInterface`] traits.
17	pub struct NonInteractiveUI {
18	    mode: OutputMode,
19	    #[allow(dead_code)]
20	    is_ci: bool,
21	}
22	
23	impl NonInteractiveUI {
24	    /// Create a new non-interactive UI.
25	    pub fn new(mode: OutputMode) -> Self {
26	        Self {
27	            mode,
28	            is_ci: crate::shell::is_ci(),
29	        }
30	    }
31	
32	    /// Create with explicit CI flag (for testing).
33	    pub fn with_ci(mode: OutputMode, is_ci: bool) -> Self {
34	        Self { mode, is_ci }
35	    }
36	}
