38	impl OutputWriter for NonInteractiveUI {
39	    fn message(&mut self, msg: &str) {
40	        if self.mode.shows_status() {
41	            println!("{}", msg);
42	        }
43	    }
44	
45	    fn success(&mut self, msg: &str) {
46	        if self.mode.shows_status() {
47	            println!("✓ {}", msg);
48	        }
49	    }
50	
51	    fn warning(&mut self, msg: &str) {
52	        if self.mode.shows_status() {
53	            eprintln!("⚠ {}", msg);
54	        }
55	    }
56	
57	    fn error(&mut self, msg: &str) {
58	        eprintln!("✗ {}", msg);
59	    }
60	
61	    fn show_hint(&mut self, hint: &str) {
62	        if self.mode.shows_status() {
63	            println!("  💡 {}", hint);
64	        }
65	    }
66	
67	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
68	        let pad = " ".repeat(indent);
69	        eprintln!();
70	        eprintln!("{}┌─ Command ──────────────────────────", pad);
71	        eprintln!("{}│ {}", pad, command);
72	        if !output.is_empty() {
73	            eprintln!("{}├─ Output ───────────────────────────", pad);
74	            for line in output.lines() {
75	                eprintln!("{}│ {}", pad, line);
76	            }
77	        }
78	        eprintln!("{}└────────────────────────────────────", pad);
79	        if let Some(h) = hint {
80	            eprintln!();
81	            eprintln!("{}Hint: {}", pad, h);
82	        }
83	    }
84	}
