1	//! Low-level terminal surface for the run path.
2	//!
3	//! `TerminalSurface` owns the [`MultiProgress`] that coordinates pinned and
4	//! transient regions during a workflow run. It is the only place that
5	//! touches the multi-progress directly — higher layers (`WorkflowDisplay`,
6	//! `StepDisplay`) only see *regions*, not bars.
7	//!
8	//! ## Regions, top to bottom
9	//!
10	//! 1. **Scrollback** — printed via [`TerminalSurface::println`]. Step
11	//!    headers, status messages, error blocks, summaries — anything
12	//!    non-spinner.
13	//! 2. **Transient region** — currently-running step's spinner with its
14	//!    bounded live-output tail. Mounted via
15	//!    [`TerminalSurface::transient_above_pinned`].
16	//! 3. **Pinned region** — workflow progress bar, pinned at the bottom.
17	//!    Mounted via [`TerminalSurface::pin_bottom`].
18	//!
19	//! ## Region clearing
20	//!
21	//! [`TransientRegion`] takes a `max_lines` hint at construction time so
22	//! callers can reason about the maximum vertical extent of the spinner
23	//! and its live-output tail. Clearing on drop currently delegates to
24	//! `indicatif::ProgressBar::finish_and_clear`, which tracks the bar's
25	//! last rendered height and clears that many rows. An earlier version
26	//! of this module padded every message to exactly `max_lines` blank
27	//! rows before clearing, but that pattern caused trailing blank rows
28	//! to leak into scrollback on drop — `finish_and_clear` already handles
29	//! the multi-line case correctly in current `indicatif` versions.
30	//!
31	//! ## Cursor freeing
32	//!
33	//! Interactive prompts (dialoguer) need exclusive access to the cursor.
34	//! [`TerminalSurface::with_cursor_freed`] hides the multi-progress draw
35	//! target for the duration of a closure and restores it afterwards.
36	
37	use indicatif::{MultiProgress, ProgressBar, ProgressDrawTarget, ProgressStyle};
38	use std::sync::Arc;
39	
40	/// Owns the [`MultiProgress`] that coordinates draw regions during a run.
41	///
42	/// Construct via [`TerminalSurface::new`] and share via the returned
43	/// [`Arc`]. Both the workflow display and per-step displays hold a clone of
44	/// the `Arc`, but only the surface itself owns mutable access to the
45	/// underlying multi-progress.
46	pub struct TerminalSurface {
47	    multi: MultiProgress,
48	}
49	
50	impl TerminalSurface {
51	    /// Create a new surface, returning a shared handle.
52	    pub fn new() -> Arc<Self> {
53	        Arc::new(Self {
54	            multi: MultiProgress::new(),
55	        })
56	    }
57	
58	    /// Try to create a surface for the current terminal.
59	    ///
60	    /// Returns `None` when the terminal can't render progress bars —
61	    /// non-TTY stderr, `NO_COLOR`, or `TERM=dumb`. In those cases
62	    /// `MultiProgress::stderr()` is silently hidden by indicatif and
63	    /// every `println` call becomes a no-op, swallowing all output.
64	    /// Callers should fall back to plain stdout writes (typically by
65	    /// using [`crate::runner::display::NonInteractiveWorkflowDisplay`]).
66	    pub fn try_new() -> Option<Arc<Self>> {
67	        if !console::Term::stderr().features().colors_supported() {
68	            return None;
69	        }
70	        Some(Self::new())
71	    }
72	
73	    /// Create a hidden surface for tests — no output is drawn.
74	    pub fn hidden() -> Arc<Self> {
75	        Arc::new(Self {
76	            multi: MultiProgress::with_draw_target(ProgressDrawTarget::hidden()),
77	        })
78	    }
79	
80	    /// Print a line into scrollback, above any pinned/transient bars.
81	    pub fn println(&self, line: &str) {
82	        // `MultiProgress::println` writes above all managed bars. If draw
83	        // is hidden (tests / silent mode), the call is a no-op rather than
84	        // an error — discard the result either way.
85	        let _ = self.multi.println(line);
86	    }
87	
88	    /// Pin a bar at the bottom of the live region.
89	    ///
90	    /// Used once per run, by the workflow display. The returned [`PinnedBar`]
91	    /// keeps the bar live until dropped; on drop, the bar is cleared.
92	    pub fn pin_bottom(self: &Arc<Self>, bar: ProgressBar) -> PinnedBar {
93	        let bar = self.multi.add(bar);
94	        PinnedBar { bar: Some(bar) }
95	    }
96	
97	    /// Mount a transient bar above the pinned region.
98	    ///
99	    /// `max_lines` records the maximum number of lines the bar will ever
100	    /// render (spinner row + live-output tail). It is informational —
101	    /// callers can read it back via [`TransientRegion::max_lines`] —
102	    /// but the actual clearing on drop delegates to
103	    /// `ProgressBar::finish_and_clear`, which tracks the rendered height
104	    /// itself.
105	    pub fn transient_above_pinned(
106	        self: &Arc<Self>,
107	        bar: ProgressBar,
108	        max_lines: usize,
109	    ) -> TransientRegion {
110	        // Insert *before* the last bar (the pinned workflow bar), so the
111	        // transient renders above it. If no bar is pinned, this is
112	        // equivalent to a normal add.
113	        let bar = self.multi.insert_from_back(1, bar);
114	        TransientRegion {
115	            bar: Some(bar),
116	            max_lines: max_lines.max(1),
117	        }
118	    }
119	
120	    /// Hide every bar for the duration of `f`, then restore.
121	    ///
122	    /// Used by step prompts. Encapsulates the
123	    /// `set_draw_target(hidden) / set_draw_target(stderr)` pattern so the
124	    /// rest of the codebase doesn't need to coordinate it.
125	    pub fn with_cursor_freed<R>(&self, f: impl FnOnce() -> R) -> R {
126	        self.multi.set_draw_target(ProgressDrawTarget::hidden());
127	        let result = f();
128	        self.multi.set_draw_target(ProgressDrawTarget::stderr());
129	        result
130	    }
131	}
132	
133	/// Handle for a bar pinned at the bottom of the live region.
134	///
135	/// On drop the bar is cleared.
136	pub struct PinnedBar {
137	    bar: Option<ProgressBar>,
138	}
139	
140	impl PinnedBar {
141	    /// Update the bar's message.
142	    pub fn set_message(&self, msg: impl Into<String>) {
143	        if let Some(bar) = &self.bar {
144	            bar.set_message(msg.into());
145	        }
146	    }
147	
148	    /// Get a clone of the underlying [`ProgressBar`] (for advanced usage).
149	    pub fn bar_clone(&self) -> Option<ProgressBar> {
150	        self.bar.clone()
151	    }
152	}
153	
154	impl Drop for PinnedBar {
155	    fn drop(&mut self) {
156	        if let Some(bar) = self.bar.take() {
157	            bar.finish_and_clear();
158	        }
159	    }
160	}
161	
162	/// Handle for a transient bar mounted above the pinned region.
163	///
164	/// On drop the bar is cleared via `ProgressBar::finish_and_clear`. The
165	/// `max_lines` field is the *maximum* vertical extent the caller
166	/// committed to when mounting — it's exposed for tests and assertions
167	/// but no longer drives clearing directly.
168	pub struct TransientRegion {
169	    bar: Option<ProgressBar>,
170	    max_lines: usize,
171	}
172	
173	impl TransientRegion {
174	    /// Update the bar's message.
175	    ///
176	    /// Indicatif's bar tracks the current rendered height across ticks
177	    /// and clears it correctly on `finish_and_clear`, so the message is
178	    /// passed through untouched (no blank-line padding) — padding to a
179	    /// fixed height was causing extra blank rows to leak into
180	    /// scrollback when the bar was finally dropped.
181	    pub fn set_message(&self, msg: &str) {
182	        if let Some(bar) = &self.bar {
183	            bar.set_message(msg.to_string());
184	        }
185	    }
186	
187	    /// Get a clone of the underlying [`ProgressBar`] for live-output
188	    /// callbacks. Callers must pad messages to `max_lines` themselves
189	    /// when bypassing [`Self::set_message`].
190	    pub fn bar_clone(&self) -> Option<ProgressBar> {
191	        self.bar.clone()
192	    }
193	
194	    /// Maximum number of lines this region will ever render.
195	    pub fn max_lines(&self) -> usize {
196	        self.max_lines
197	    }
198	
199	    /// Replace the bar style with a static `{msg}` template.
200	    ///
201	    /// Used by `finish_*` methods on [`StepDisplay`] when leaving a
202	    /// styled result line in scrollback. The caller should follow this
203	    /// with [`Self::finish_with_message`] or the bar will be cleared on
204	    /// drop.
205	    pub fn freeze_style(&self) {
206	        if let Some(bar) = &self.bar {
207	            bar.set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
208	        }
209	    }
210	
211	    /// Finish the region with a final message and consume the handle.
212	    ///
213	    /// Unlike `Drop`, this leaves the message in scrollback (collapsed to
214	    /// a single line via the `{msg}` template).
215	    pub fn finish_with_line(mut self, line: &str) {
216	        if let Some(bar) = self.bar.take() {
217	            bar.set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
218	            bar.finish_with_message(line.to_string());
219	        }
220	    }
221	}
222	
223	impl Drop for TransientRegion {
224	    fn drop(&mut self) {
225	        if let Some(bar) = self.bar.take() {
226	            // Indicatif tracks the bar's last rendered height and
227	            // clears that many rows on `finish_and_clear`. Don't mess
228	            // with the message before clearing — earlier attempts to
229	            // "normalize" the height by overwriting the message with
230	            // blank lines caused those blanks to be baked into
231	            // scrollback below the cleared region.
232	            bar.finish_and_clear();
233	        }
234	    }
235	}
