10	/// Renders a confirm prompt.
11	///
12	/// ## Example
13	///
14	/// ```rust,no_run
15	/// use dialoguer::Confirm;
16	///
17	/// fn main() {
18	///     let confirmation = Confirm::new()
19	///         .with_prompt("Do you want to continue?")
