27	///     }
28	/// }
29	/// ```
30	#[derive(Clone)]
31	pub struct Confirm<'a> {
32	    prompt: String,
33	    report: bool,
34	    default: Option<bool>,
35	    show_default: bool,
36	    wait_for_newline: bool,
37	    theme: &'a dyn Theme,
38	}
