204	    ///         .interact()
205	    ///         .unwrap();
206	    /// }
207	    /// ```
208	    pub fn with_theme(theme: &'a dyn Theme) -> Self {
209	        Self {
210	            prompt: "".into(),
211	            report: true,
212	            theme,
213	            allow_empty_password: false,
214	            confirmation_prompt: None,
215	            validator: None,
216	        }
217	    }
