179	    #[inline]
180	    pub fn interact_on(self, term: &Term) -> Result<usize> {
181	        Ok(self
182	            ._interact_on(term, false)?
183	            .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "Quit not allowed in this case"))?)
184	    }
