186	    /// Like [`interact_opt`](Self::interact_opt) but allows a specific terminal to be set.
187	    #[inline]
188	    pub fn interact_on_opt(self, term: &Term) -> Result<Option<usize>> {
189	        self._interact_on(term, true)
190	    }
