397	        if let Some(ref buffer) = self.inner.buffer {
398	            let mut buffer = buffer.lock().unwrap();
399	            if !buffer.is_empty() {
400	                self.write_through(&buffer[..])?;
401	                buffer.clear();
402	            }
403	        }
404	        Ok(())
405	    }
