556	    pub(crate) fn write_through_common(&self, bytes: &[u8]) -> io::Result<()> {
557	        match self.inner.target {
558	            TermTarget::Stdout => {
559	                io::stdout().write_all(bytes)?;
560	                io::stdout().flush()?;
