252	fn read_single_key_impl(fd: RawFd) -> Result<Key, io::Error> {
253	    loop {
254	        match read_single_char(fd)? {
255	            Some('\x1b') => {
256	                // Escape was read, keep reading in case we find a familiar key
257	                break if let Some(c1) = read_single_char(fd)? {
258	                    if c1 == '[' {
259	                        if let Some(c2) = read_single_char(fd)? {
260	                            match c2 {
261	                                'A' => Ok(Key::ArrowUp),
262	                                'B' => Ok(Key::ArrowDown),
263	                                'C' => Ok(Key::ArrowRight),
264	                                'D' => Ok(Key::ArrowLeft),
265	                                'H' => Ok(Key::Home),
266	                                'F' => Ok(Key::End),
267	                                'Z' => Ok(Key::BackTab),
268	                                _ => {
269	                                    let c3 = read_single_char(fd)?;
270	                                    if let Some(c3) = c3 {
271	                                        if c3 == '~' {
272	                                            match c2 {
273	                                                '1' => Ok(Key::Home), // tmux
274	                                                '2' => Ok(Key::Insert),
275	                                                '3' => Ok(Key::Del),
276	                                                '4' => Ok(Key::End), // tmux
277	                                                '5' => Ok(Key::PageUp),
278	                                                '6' => Ok(Key::PageDown),
279	                                                '7' => Ok(Key::Home), // xrvt
280	                                                '8' => Ok(Key::End),  // xrvt
281	                                                _ => Ok(Key::UnknownEscSeq(vec![c1, c2, c3])),
282	                                            }
283	                                        } else {
284	                                            Ok(Key::UnknownEscSeq(vec![c1, c2, c3]))
285	                                        }
286	                                    } else {
287	                                        // \x1b[ and 1 more char
288	                                        Ok(Key::UnknownEscSeq(vec![c1, c2]))
289	                                    }
290	                                }
291	                            }
292	                        } else {
293	                            // \x1b[ and no more input
294	                            Ok(Key::UnknownEscSeq(vec![c1]))
295	                        }
296	                    } else {
297	                        // char after escape is not [
298	                        Ok(Key::UnknownEscSeq(vec![c1]))
299	                    }
300	                } else {
301	                    //nothing after escape
302	                    Ok(Key::Escape)
303	                };
304	            }
305	            Some(c) => {
306	                let byte = c as u8;
307	                let mut buf: [u8; 4] = [byte, 0, 0, 0];
308	
309	                break if byte & 224u8 == 192u8 {
310	                    // a two byte unicode character
311	                    read_bytes(fd, &mut buf[1..], 1)?;
312	                    Ok(key_from_utf8(&buf[..2]))
313	                } else if byte & 240u8 == 224u8 {
314	                    // a three byte unicode character
315	                    read_bytes(fd, &mut buf[1..], 2)?;
316	                    Ok(key_from_utf8(&buf[..3]))
317	                } else if byte & 248u8 == 240u8 {
318	                    // a four byte unicode character
319	                    read_bytes(fd, &mut buf[1..], 3)?;
320	                    Ok(key_from_utf8(&buf[..4]))
321	                } else {
322	                    Ok(match c {
323	                        '\n' | '\r' => Key::Enter,
324	                        '\x7f' => Key::Backspace,
325	                        '\t' => Key::Tab,
326	                        '\x01' => Key::Home,      // Control-A (home)
327	                        '\x05' => Key::End,       // Control-E (end)
328	                        '\x08' => Key::Backspace, // Control-H (8) (Identical to '\b')
329	                        _ => Key::Char(c),
330	                    })
331	                };
332	            }
333	            None => {
334	                // there is no subsequent byte ready to be read, block and wait for input
335	                // negative timeout means that it will block indefinitely
336	                match select_or_poll_term_fd(fd, -1) {
337	                    Ok(_) => continue,
338	                    Err(_) => break Err(io::Error::last_os_error()),
339	                }
340	            }
341	        }
342	    }
343	}
