345	pub(crate) fn read_single_key(ctrlc_key: bool) -> io::Result<Key> {
346	    let input = Input::unbuffered()?;
347	
348	    let mut termios = core::mem::MaybeUninit::uninit();
349	    c_result(|| unsafe { libc::tcgetattr(input.as_raw_fd(), termios.as_mut_ptr()) })?;
350	    let mut termios = unsafe { termios.assume_init() };
351	    let original = termios;
352	    make_raw(&mut termios);
353	    termios.c_oflag = original.c_oflag;
354	    c_result(|| unsafe { libc::tcsetattr(input.as_raw_fd(), libc::TCSADRAIN, &termios) })?;
355	    let rv = read_single_key_impl(input.as_raw_fd());
356	    c_result(|| unsafe { libc::tcsetattr(input.as_raw_fd(), libc::TCSADRAIN, &original) })?;
357	
358	    // if the user hit ^C we want to signal SIGINT to ourselves.
359	    if let Err(ref err) = rv {
360	        if err.kind() == io::ErrorKind::Interrupted {
361	            if !ctrlc_key {
362	                unsafe {
363	                    libc::raise(libc::SIGINT);
364	                }
365	            } else {
366	                return Ok(Key::CtrlC);
367	            }
368	        }
369	    }
370	
371	    rv
372	}
