374	fn key_from_utf8(buf: &[u8]) -> Key {
375	    if let Ok(s) = str::from_utf8(buf) {
376	        if let Some(c) = s.chars().next() {
377	            return Key::Char(c);
378	        }
379	    }
380	    Key::Unknown
381	}
