413	    termios.c_oflag &= !libc::OPOST;
414	    termios.c_lflag &= !(libc::ECHO | libc::ECHONL | libc::ICANON | libc::ISIG | libc::IEXTEN);
415	    termios.c_cflag &= !(libc::CSIZE | libc::PARENB);
416	    termios.c_cflag |= libc::CS8;
