201	fn select_or_poll_term_fd(fd: RawFd, timeout: i32) -> io::Result<bool> {
202	    // There is a bug on macos that ttys cannot be polled, only select()
203	    // works.  However given how problematic select is in general, we
204	    // normally want to use poll there too.
205	    #[cfg(target_os = "macos")]
206	    {
207	        if unsafe { libc::isatty(fd) == 1 } {
208	            return select_fd(fd, timeout);
209	        }
210	    }
211	    poll_fd(fd, timeout)
212	}
