/// Prompt the user for input.
///
/// Before showing any interactive prompt, checks for an environment variable
/// matching the prompt key (e.g., `BUMP=minor` for a prompt with key "bump").
/// This works in both interactive and non-interactive modes.
///
/// Wraps the underlying prompt in `catch_unwind` so that panics from
/// `console`/`dialoguer` (e.g. EOF from Ctrl+D on certain terminals)
/// are converted to a clean IO error instead of crashing the process.
pub fn prompt_user(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    if let Some(result) = env_override(prompt) {
        return Ok(result);
    }

    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        match &prompt.prompt_type {
            PromptType::Confirm => prompt_confirm(prompt, term),
            PromptType::Input => prompt_input(prompt, term),
            PromptType::Select { options } => prompt_select(prompt, options, term),
            PromptType::MultiSelect { options } => prompt_multiselect(prompt, options, term),
        }
    }));

    match result {
        Ok(inner) => inner,
        Err(_) => {
            // Restore terminal state that dialoguer/console may have left
            // dirty (hidden cursor, raw mode) before the panic.
            term.show_cursor().ok();
            Err(BivvyError::Io(std::io::Error::new(
                std::io::ErrorKind::Interrupted,
                "Prompt interrupted (EOF)",
            )))
        }
    }
}

